document.addEventListener("DOMContentLoaded",function(){const d=document.querySelector(".navbar-church");if(d){window.addEventListener("scroll",function(){if(window.scrollY>40){d.classList.add("shadow-sm")}else{d.classList.remove("shadow-sm")}})}const c=document.getElementById("blog-preview");if(c&&typeof PostsStore!=="undefined"){const e=PostsStore.getAll().filter(d=>d.status==="Published").slice(0,3);c.innerHTML=e.map(d=>'<div class="col-md-4">'+'<div class="card church-card h-100">'+'<div class="card-thumb"><i class="bi bi-image"></i></div>'+'<div class="card-body">'+'<div class="card-meta mb-2">'+d.category+" &bull; "+s(d.date)+"</div>"+'<h3 class="card-title">'+t(d.title)+"</h3>"+'<p class="text-muted small">'+t(d.excerpt)+"</p>"+'<a href="blog-detail.html?id='+d.id+'" class="fw-bold text-red small text-uppercase">Baca Selengkapnya &rarr;</a>'+"</div>"+"</div>"+"</div>").join("")}function s(d){const c=new Date(d);return c.toLocaleDateString("id-ID",{day:"numeric",month:"short",year:"numeric"})}function t(d){const c=document.createElement("div");c.textContent=d;return c.innerHTML}});